import { beforeEach, describe, expect, it, vi } from "vitest";
const mocks = vi.hoisted(() => ({
  run: vi.fn(),
  ensure: vi.fn(),
  user: vi.fn(),
  update: vi.fn(),
  cancel: vi.fn(),
  lock: vi.fn(),
}));
vi.mock("@/lib/deletion-jobs", () => ({
  runDeletionJob: mocks.run,
  ensureDeletionJob: mocks.ensure,
  DELETION_DRAIN_MS: 900000,
  DELETION_RETENTION_MS: 2592000000,
}));
vi.mock("@/lib/cancellation", () => ({ cancelQueuedIn: mocks.cancel }));
vi.mock("@/lib/db", () => {
  const tx = {
    user: { findUnique: mocks.user, update: mocks.update },
    $queryRaw: mocks.lock,
  };
  return { db: { $transaction: (work: (tx: unknown) => unknown) => work(tx) } };
});
import { requestAccountDeletion, cleanupDeletedAccount } from "@/lib/account";
beforeEach(() => {
  vi.resetAllMocks();
  mocks.run.mockResolvedValue(false);
  mocks.cancel.mockResolvedValue({ cancelled: 2, couldNotStop: 1 });
});
describe("account deletion request", () => {
  it("requires the exact email before any mutation", async () => {
    mocks.user.mockResolvedValue({ email: "[REDACTED_EMAIL]" });
    await expect(
      requestAccountDeletion("owner", "[REDACTED_EMAIL]"),
    ).rejects.toThrow("exactly");
    expect(mocks.update).not.toHaveBeenCalled();
    expect(mocks.run).not.toHaveBeenCalled();
  });
  it("preserves the first timestamp and transfers recovery before erasing the credential", async () => {
    const requestedAt = new Date("2026-01-01T12:00:00Z");
    mocks.user.mockResolvedValue({
      email: "[REDACTED_EMAIL]",
      deletionRequestedAt: requestedAt,
    });
    expect(await requestAccountDeletion("owner", "[REDACTED_EMAIL]")).toEqual(
      { cancelled: 2, couldNotStop: 1 },
    );
    expect(mocks.update.mock.calls[0][0]).toMatchObject({
      where: { id: "owner" },
      data: { deletionRequestedAt: requestedAt, gmailAuthorized: false },
    });
    expect(mocks.ensure.mock.invocationCallOrder[0]).toBeLessThan(
      mocks.update.mock.invocationCallOrder[1],
    );
    expect(mocks.run).toHaveBeenCalledWith("owner", expect.any(Date), {
      billingOnly: true,
    });
    expect(mocks.cancel.mock.invocationCallOrder[0]).toBeLessThan(
      mocks.run.mock.invocationCallOrder[0],
    );
  });
  it("leaves the durable request accepted when immediate recovery fails", async () => {
    mocks.user.mockResolvedValue({
      email: "[REDACTED_EMAIL]",
      deletionRequestedAt: null,
    });
    mocks.run.mockRejectedValue(new Error("provider down"));
    await expect(
      requestAccountDeletion("owner", "[REDACTED_EMAIL]"),
    ).resolves.toMatchObject({ cancelled: 2 });
  });
  it("passes controlled clocks through to independent recovery", async () => {
    const now = new Date();
    mocks.run.mockResolvedValue(false);
    expect(await cleanupDeletedAccount("owner", now)).toBe(false);
    expect(mocks.run).toHaveBeenCalledWith("owner", now);
  });
});
